import{EngineError,requireValue,normalizeResourceError,resourceAllocationKind}from'./errors.js';import{allocateTypedArray}from'./allocation.js';import{createZeroRetirement as createRetirement}from'./zero-native-context-plan.js';import{retireCompositeOwners}from'./composite-owner-release.js';
// Private immutable cuts of one already-verified original model, for one run.
// The cache finances the host bytes, Blob transport copy and metadata. A loan
// independently holds the original graph-build workspace, so pressure may
// detach that one entry before refunding the optional cache credit.
export function createEfficientLoFtrStageCache({budget,workspaceBudget,workspaceBytes,limitBytes=128*1024**2}={}){
 requireValue(Number.isSafeInteger(limitBytes)&&limitBytes>0&&Number.isSafeInteger(workspaceBytes)&&workspaceBytes>0,'Bounded native graph cache required.');let fee;try{fee=budget.reserve(limitBytes);}catch(e){if(e?.code==='MEMORY_LIMIT')return null;throw e;}
 const entries=new Map(),detached=new Set();let bytes=0,closed=false,closing;const stats={hits:0,misses:0,evictions:0,storedGraphs:0,currentBytes:0,peakBytes:0,limitBytes,disabledByPressure:false};
 const entryBytes=s=>2*s.bytes.byteLength+65536+JSON.stringify({inputs:s.inputs,outputs:s.outputs,nodes:s.nativeNodeNames,initializers:s.nativeInitializerNames}).length*4;
 async function retire(e){if(e.refs){e.detached=true;detached.add(e);return;}await e.owner.dispose();detached.delete(e);}
 async function remove(key,e){await retire(e);if(entries.get(key)===e){entries.delete(key);bytes-=e.size;stats.storedGraphs=entries.size;stats.currentBytes=bytes;}}
 const api={stats,get enabled(){return!closed;},
  borrow(key){if(closed)return null;const e=entries.get(key);if(!e){stats.misses++;return null;}const free=workspaceBudget.reserve(workspaceBytes);entries.delete(key);entries.set(key,e);e.refs++;stats.hits++;let released=false,returning=false;return{...e.meta,bytes:e.data,sha256:e.sha256,url:e.url,cached:true,async dispose(){if(released)return;if(e.refs>0&&!returning){returning=true;e.refs--;}if(e.detached&&e.refs===0)await retire(e);await free();released=true;}};},
  async put(key,stage,sha256){if(closed||entries.has(key))return false;const size=entryBytes(stage);if(size>limitBytes)return false;while(bytes+size>limitBytes){const[k,e]=entries.entries().next().value;await remove(k,e);stats.evictions++;}let optionalFailure=false;const modelBytes=stage.bytes.byteLength,e={size,refs:0,data:null,url:null,sha256,meta:null,owner:createRetirement()},owner=e.owner;let backing;owner.add(()=>{if(e.url){URL.revokeObjectURL(e.url);e.url=null;}e.data=e.meta=null;},0);owner.add(async()=>{const n=await backing?.();backing=null;if(n!==0)budget.notifyBackingRelease?.('array-buffer',n??modelBytes);},1);
   try{try{e.data=allocateTypedArray(Uint8Array,stage.bytes.length,{label:'native-LoFTR-derived-graph-cache'});}catch(e){optionalFailure=e instanceof EngineError&&e.code==='MEMORY_ALLOCATION'&&resourceAllocationKind(e)==='array-buffer'&&!Object.isFrozen(e);throw e;}e.data.set(stage.bytes);backing=budget.registerBacking?.('array-buffer',e.data.byteLength,{owner:'eloftr-native',label:'immutable-derived-model',identity:e.data.buffer});e.meta=structuredClone({inputs:stage.inputs,outputs:stage.outputs,nativeNodeNames:stage.nativeNodeNames,nativeInitializerNames:stage.nativeInitializerNames});let blob;try{blob=new Blob([e.data]);e.url=URL.createObjectURL(blob);}catch(e){if(e===null||typeof e!=='object'||Object.isFrozen(e))throw e;const classified=normalizeResourceError(e,{allocationKind:'array-buffer',requestedBytes:modelBytes,label:'native-LoFTR-derived-graph-blob'});optionalFailure=classified instanceof EngineError&&classified.code==='MEMORY_ALLOCATION';throw classified;}entries.set(key,e);bytes+=size;stats.storedGraphs=entries.size;stats.currentBytes=bytes;stats.peakBytes=Math.max(stats.peakBytes,bytes);return true;}catch(primary){try{await owner.dispose();}catch(cleanup){detached.add(e);if(optionalFailure)throw cleanup;throw primary;}if(optionalFailure){stats.disabledByAllocation=true;await api.dispose();return false;}throw primary;}
  },
  dispose({pressure=false}={}){closed=true;if(pressure)stats.disabledByPressure=true;if(closing)return closing;closing=(async()=>{await retireCompositeOwners([...entries].map(([k,e])=>()=>remove(k,e)));await retireCompositeOwners([...detached].filter(e=>!e.refs).map(e=>()=>retire(e)));await fee?.();fee=null;})();void closing.catch(()=>{closing=null;});return closing;}
 };return api;
}
